// Some portions generated by Claude
import test from "node:test";
import assert from "node:assert/strict";
import {
  discoverConnections,
  connectionQuery,
} from "../../../main/frontend/graph-explorer/graph-connection-discovery.ts";
const iri = (value) => ({ type: "uri", value });
test("connection discovery intersects targets locally and preserves self-loops", async () => {
  const result = await discoverConnections(
    ["urn:a", "urn:b"],
    async (query) => {
      assert.match(query, /VALUES \?source/);
      assert.doesNotMatch(query, /VALUES \?target/);
      return {
        results: {
          bindings: [
            {
              source: iri("urn:a"),
              predicate: iri("urn:p"),
              target: iri("urn:b"),
            },
            {
              source: iri("urn:a"),
              predicate: iri("urn:p"),
              target: iri("urn:outside"),
            },
            {
              source: iri("urn:b"),
              predicate: iri("urn:p"),
              target: iri("urn:b"),
            },
          ],
        },
      };
    },
    "all",
    new AbortController().signal,
  );
  assert.equal(result.requests, 1);
  assert.equal(result.bindings.length, 2);
  assert.equal(result.bindings[1].target.value, "urn:b");
  assert.equal(result.truncatedSources, 0);
});
test("connection query size grows with one source batch, not the loaded graph squared", () => {
  const query = connectionQuery(
    Array.from({ length: 128 }, (_, i) => `urn:node:${i}`),
    "default",
  );
  assert.ok(query.length < 5000);
  assert.match(query, /LIMIT 4096/);
});
